// 가짜 본체: contracts/examples/support.json 의 응답 예시를 질문 낱말 · simulate 로 골라 돌려줌.
// 시험 도구 · 화면 연결 확인용. 판단을 하지 않으므로 이 결과는 결과서에 쓰지 않는다.
const R = {"자동 답변": {"request_id": "wf01", "route": "자동 답변", "answer": "준비금 10만 원을 먼저 빼고 남은 현금을 세어 포스 현금 합계와 맞춰요. 계산대마다 따로 해요 [1].", "sources": [{"doc": "closing-checklist", "section": "2. 문 닫은 뒤 — 돈 맞추기 (처방 검수, 카드, 현금 순서)", "score": 0.61}], "ticket": null, "agents": ["triage", "retriever", "writer", "verifier"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "", "timings": {"total_ms": 2840}}, "보완 질문": {"request_id": "wf02", "route": "보완 질문", "answer": "더 알려 주세요: 어느 단계에서 (포스, 카드 단말기, 청구 프로그램), 화면에 뜬 문구", "sources": [], "ticket": null, "agents": ["triage"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "", "timings": {"total_ms": 900}}, "담당자 이관": {"request_id": "wf12", "route": "담당자 이관", "answer": "진열대와 창고에서 같은 제조번호를 바로 빼서 따로 보관해 주세요 [1]. 당일 책임 약사에게 긴급으로 넘겼어요.\nR-1001: 약국장 확인 중 (2026-11-04)", "sources": [{"doc": "recall-first-response", "section": "2. 진열대에서 바로 빼기", "score": 0.58}], "ticket": {"ticket_id": "T-2003", "priority": "high", "duplicate": false}, "agents": ["triage", "retriever", "writer", "verifier", "handoff"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "urgent", "timings": {"total_ms": 4100}}, "권한 없음": {"request_id": "wf06", "route": "권한 없음", "answer": "본인이 접수한 건만 확인할 수 있어요.", "sources": [], "ticket": null, "agents": ["triage"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "not_your_record", "timings": {"total_ms": 700}}, "차단": {"request_id": "wf08", "route": "차단", "answer": "이 요청은 처리할 수 없어요. 업무 질문을 다시 보내 주세요.", "sources": [], "ticket": null, "agents": [], "security": {"blocked_by": "rule", "reason": "ignore_instructions", "masked": 0}, "reason": "", "timings": {"total_ms": 40}}, "어르신 자동 답변": {"request_id": "t31", "route": "자동 답변", "answer": "콧물 감기약에 든 클로르페니라민 같은 항히스타민 성분은 졸음이 올 수 있어요 [1].\nAI가 공공 의약품 정보를 정리한 안내예요. 복용 판단은 약사와 상의하세요.", "sources": [{"doc": "senior-cold-sleep-stomach", "section": "2. 감기 · 콧물 약 성분", "score": 0.55}], "ticket": null, "agents": ["triage", "retriever", "writer", "verifier"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "", "timings": {"total_ms": 3100}}, "티켓 실패": {"request_id": "wf04", "route": "담당자 이관", "answer": "담당자에게 넘기는 중 접수 시스템이 응답하지 않았어요. 요청은 보관해 두었고 확인되는 대로 연락드려요.", "sources": [], "ticket": null, "agents": ["triage", "handoff"], "security": {"blocked_by": "", "reason": "", "masked": 0}, "reason": "tickets_down", "timings": {"total_ms": 3500}}};
const INVALID = {"error": "invalid request", "codes": ["question_required"]};
const b = $json.body ?? {};
const q = String(b.question ?? '').trim();
const codes = [];
if (!b.request_id || String(b.request_id).length > 64) codes.push('request_id_required');
if (!q) codes.push('question_required');
if (q.length > 500) codes.push('too_long');
if (!b.user) codes.push('unknown_user');
if (codes.length) return [{ json: { status: 400, body: { ...INVALID, codes } } }];
const has = re => re.test(q);
let key = '자동 답변';
if (b.simulate === 'tickets_down') key = '티켓 실패';
else if (has(/이전 지시|무시하고|시스템 프롬프트|관리자 모드/)) key = '차단';
else if (has(/R-1002/)) key = '권한 없음';
else if (has(/회수|숨이 차|냉장고|제 돈|정수기|공유기|단말기가 안/)) key = '담당자 이관';
else if (has(/마감이 안 돼요|같이 먹어도/) && !b.context) key = '보완 질문';
else if (has(/졸려|감기약|어르신|드셔/)) key = '어르신 자동 답변';
const body = { ...JSON.parse(JSON.stringify(R[key])), request_id: String(b.request_id) };
return [{ json: { status: 200, body } }];
